// Studio scenes (pass 3): Blender-authored GLB sculptures rendered in a Cinema 4D "studio abstract" look.
// Used by Tunnel, Kaleido and Plasma (all rebuilt as real 3D). Assets: public/studio/<scene>.glb + .json,
// generated by tools/blender/studio_scenes.py. Original MIT-licensed work. No Shadertoy code.

import { parseGlb, parseCameraPath, sampleCameraPath, type CameraPath, type Vec3 } from './gltf';
import * as SS from './studio_shaders';

export type StudioLook = {
  bgTop: string; bgBottom: string; glow: string;
  slots: [string, string, string, string, string, string, string];
  key: string; fill: string; rim: string; dome: string;
  keyI: number; domeI: number;
};

