/** Object pigments that stay distinct from each look's cove (bgTop / bgBottom).
 *  Used by 3D Fractal so clay bands cannot disappear into the backdrop. */
export const FRACTAL_PIGMENT: Record<string, { c1: string; mid: string; c2: string }> = {
  'Lilac Dream':   { c1: '#d45a86', mid: '#d9b56a', c2: '#4f54c8' },
  'Coral Peach':   { c1: '#c43a32', mid: '#e08940', c2: '#3d4cc0' },
  'Cobalt Orange': { c1: '#ff8a2a', mid: '#ffc05e', c2: '#f6e8d4' },
  'Mint Pink':     { c1: '#c44878', mid: '#2aae9e', c2: '#5a3fa8' },
  'Cream Gold':    { c1: '#8c6648', mid: '#c4955c', c2: '#5c3a22' },
  'Red Studio':    { c1: '#3ec8c0', mid: '#eaa43c', c2: '#f4e4d2' },
};

export function fractalPigment(lookName: string): { c1: string; mid: string; c2: string } {
  return FRACTAL_PIGMENT[lookName] ?? FRACTAL_PIGMENT['Lilac Dream'];
}

export const STUDIO_MATS = ['Scene', 'Matte', 'Gloss', 'Iridescent', 'Satin metal'];

export function srgbHex(h: string): Vec3 {
  const n = parseInt(h.replace('#', ''), 16);
  const f = (c: number) => { c /= 255; return c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4); };
  return [f((n >> 16) & 255), f((n >> 8) & 255), f(n & 255)];
}

type Prog = { p: WebGLProgram; u: Record<string, WebGLUniformLocation | null> };
function compile(gl: WebGL2RenderingContext, vs: string, fs: string, name: string): Prog {
  const prog = gl.createProgram()!;
  for (const [type, src] of [[gl.VERTEX_SHADER, vs], [gl.FRAGMENT_SHADER, fs]] as const) {
    const sh = gl.createShader(type)!;
    gl.shaderSource(sh, src); gl.compileShader(sh);
    if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS)) throw new Error(`${name}: ${gl.getShaderInfoLog(sh)}`);
    gl.attachShader(prog, sh);
  }
  gl.linkProgram(prog);
  if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) throw new Error(`${name} link: ${gl.getProgramInfoLog(prog)}`);
  const u: Record<string, WebGLUniformLocation | null> = {};
  const n = gl.getProgramParameter(prog, gl.ACTIVE_UNIFORMS);
  for (let i = 0; i < n; i++) {
    const a = gl.getActiveUniform(prog, i)!;
    u[a.name] = gl.getUniformLocation(prog, a.name);
    if (a.name.endsWith('[0]')) u[a.name.slice(0, -3)] = u[a.name];
  }
  return { p: prog, u };
}

const sub = (a: Vec3, b: Vec3): Vec3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const dot = (a: Vec3, b: Vec3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const cross = (a: Vec3, b: Vec3): Vec3 => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const norm = (a: Vec3): Vec3 => { const l = Math.hypot(a[0], a[1], a[2]) || 1; return [a[0] / l, a[1] / l, a[2] / l]; };
function mul(a: number[], b: number[]): number[] {
  const o = new Array(16).fill(0);
  for (let c = 0; c < 4; c++) for (let r = 0; r < 4; r++) for (let k = 0; k < 4; k++) o[c * 4 + r] += a[k * 4 + r] * b[c * 4 + k];
  return o;
}
function lookAt(e: Vec3, t: Vec3, up: Vec3): number[] {
  const z = norm(sub(e, t)), x = norm(cross(up, z)), y = cross(z, x);
  return [x[0], y[0], z[0], 0, x[1], y[1], z[1], 0, x[2], y[2], z[2], 0, -dot(x, e), -dot(y, e), -dot(z, e), 1];
}
function perspective(fovy: number, aspect: number, near: number, far: number): number[] {
  const f = 1 / Math.tan(fovy / 2);
  return [f / aspect, 0, 0, 0, 0, f, 0, 0, 0, 0, (far + near) / (near - far), -1, 0, 0, (2 * far * near) / (near - far), 0];
}
function ortho(l: number, r: number, b: number, t: number, n: number, f: number): number[] {
  return [2 / (r - l), 0, 0, 0, 0, 2 / (t - b), 0, 0, 0, 0, -2 / (f - n), 0, -(r + l) / (r - l), -(t + b) / (t - b), -(f + n) / (f - n), 1];
}
/** General 4x4 inverse (column-major). */
export function invert(m: number[]): number[] {
  const inv = new Array(16);
  inv[0] = m[5] * m[10] * m[15] - m[5] * m[11] * m[14] - m[9] * m[6] * m[15] + m[9] * m[7] * m[14] + m[13] * m[6] * m[11] - m[13] * m[7] * m[10];
  inv[4] = -m[4] * m[10] * m[15] + m[4] * m[11] * m[14] + m[8] * m[6] * m[15] - m[8] * m[7] * m[14] - m[12] * m[6] * m[11] + m[12] * m[7] * m[10];
  inv[8] = m[4] * m[9] * m[15] - m[4] * m[11] * m[13] - m[8] * m[5] * m[15] + m[8] * m[7] * m[13] + m[12] * m[5] * m[11] - m[12] * m[7] * m[9];
  inv[12] = -m[4] * m[9] * m[14] + m[4] * m[10] * m[13] + m[8] * m[5] * m[14] - m[8] * m[6] * m[13] - m[12] * m[5] * m[10] + m[12] * m[6] * m[9];
  inv[1] = -m[1] * m[10] * m[15] + m[1] * m[11] * m[14] + m[9] * m[2] * m[15] - m[9] * m[3] * m[14] - m[13] * m[2] * m[11] + m[13] * m[3] * m[10];
  inv[5] = m[0] * m[10] * m[15] - m[0] * m[11] * m[14] - m[8] * m[2] * m[15] + m[8] * m[3] * m[14] + m[12] * m[2] * m[11] - m[12] * m[3] * m[10];
  inv[9] = -m[0] * m[9] * m[15] + m[0] * m[11] * m[13] + m[8] * m[1] * m[15] - m[8] * m[3] * m[13] - m[12] * m[1] * m[11] + m[12] * m[3] * m[9];
  inv[13] = m[0] * m[9] * m[14] - m[0] * m[10] * m[13] - m[8] * m[1] * m[14] + m[8] * m[2] * m[13] + m[12] * m[1] * m[10] - m[12] * m[2] * m[9];
  inv[2] = m[1] * m[6] * m[15] - m[1] * m[7] * m[14] - m[5] * m[2] * m[15] + m[5] * m[3] * m[14] + m[13] * m[2] * m[7] - m[13] * m[3] * m[6];
  inv[6] = -m[0] * m[6] * m[15] + m[0] * m[7] * m[14] + m[4] * m[2] * m[15] - m[4] * m[3] * m[14] - m[12] * m[2] * m[7] + m[12] * m[3] * m[6];
  inv[10] = m[0] * m[5] * m[15] - m[0] * m[7] * m[13] - m[4] * m[1] * m[15] + m[4] * m[3] * m[13] + m[12] * m[1] * m[7] - m[12] * m[3] * m[5];
  inv[14] = -m[0] * m[5] * m[14] + m[0] * m[6] * m[13] + m[4] * m[1] * m[14] - m[4] * m[2] * m[13] - m[12] * m[1] * m[6] + m[12] * m[2] * m[5];
  inv[3] = -m[1] * m[6] * m[11] + m[1] * m[7] * m[10] + m[5] * m[2] * m[11] - m[5] * m[3] * m[10] - m[9] * m[2] * m[7] + m[9] * m[3] * m[6];
  inv[7] = m[0] * m[6] * m[11] - m[0] * m[7] * m[10] - m[4] * m[2] * m[11] + m[4] * m[3] * m[10] + m[8] * m[2] * m[7] - m[8] * m[3] * m[6];
  inv[11] = -m[0] * m[5] * m[11] + m[0] * m[7] * m[9] + m[4] * m[1] * m[11] - m[4] * m[3] * m[9] - m[8] * m[1] * m[7] + m[8] * m[3] * m[5];
  inv[15] = m[0] * m[5] * m[10] - m[0] * m[6] * m[9] - m[4] * m[1] * m[10] + m[4] * m[2] * m[9] + m[8] * m[1] * m[6] - m[8] * m[2] * m[5];
  let det = m[0] * inv[0] + m[1] * inv[4] + m[2] * inv[8] + m[3] * inv[12];
  det = det === 0 ? 1 : 1 / det;
  return inv.map((v: number) => v * det);
}

export type StudioMeta = {
  scene: string;
  layers: { axis: Vec3; pivot: Vec3; speed: number }[];
  camera: any;
  bounds: { min: Vec3; max: Vec3 };
  stats?: any;
};

type Scene = { vao: WebGLVertexArrayObject; count: number; meta: StudioMeta; path: CameraPath | null };

export type StudioParams = {
  look: string; mat: string; speed: number; dof: number; focus: number; ao: number; gloss: number;
  irid: number; rim: number; shadowSoft: number; fog: number; keyAz: number; keyEl: number; camSpeed: number; exposure?: number;
};

export type StudioRenderOpts = { target: WebGLFramebuffer; w: number; h: number; aspect: number; dt: number; params: StudioParams };

const SHADOW_RES = 2048;

/** Shared post helpers for other studio-style modes (Morph sculpt): MSAA-free DOF over an RGBA(alpha=distance) texture. */
export class StudioRenderer {
  scenes: Record<string, Scene> = {};
  errors: Record<string, string> = {};
  loading: Record<string, boolean> = {};
  lastDebug: any = null;
  private gl: WebGL2RenderingContext;
  private mesh: Prog; private shadow: Prog; private back: Prog; private dof: Prog;
  private shadowTex: WebGLTexture | null = null; private shadowFB: WebGLFramebuffer | null = null;
  private msFB: WebGLFramebuffer | null = null; private msColor: WebGLRenderbuffer | null = null; private msDepth: WebGLRenderbuffer | null = null;
  private resFB: WebGLFramebuffer | null = null; private resTex: WebGLTexture | null = null;
  private size = [0, 0]; private samples = 4;
  private t = 0; private camT = 0;
  private emptyVao: WebGLVertexArrayObject;

  constructor(gl: WebGL2RenderingContext) {
    this.gl = gl;
    this.mesh = compile(gl, SS.ST_MESH_VS, SS.ST_MESH_FS, 'studio-mesh');
    this.shadow = compile(gl, SS.ST_MESH_VS, SS.ST_SHADOW_FS, 'studio-shadow');
    this.back = compile(gl, SS.ST_QUAD_VS, SS.ST_BACK_FS, 'studio-back');
    this.dof = compile(gl, SS.ST_QUAD_VS, SS.ST_DOF_FS, 'studio-dof');
    this.emptyVao = gl.createVertexArray()!;
    const maxS = gl.getParameter(gl.MAX_SAMPLES) as number;
    this.samples = Math.max(0, Math.min(4, maxS || 0));
  }

  ready(name: string) { return !!this.scenes[name]; }

  async load(name: string, base = '/studio'): Promise<void> {
    if (this.scenes[name] || this.loading[name]) return;
    this.loading[name] = true;
    try {
      const [buf, meta] = await Promise.all([
        fetch(`${base}/${name}.glb`).then((r) => { if (!r.ok) throw new Error(`${name}.glb HTTP ${r.status}`); return r.arrayBuffer(); }),
        fetch(`${base}/${name}.json`).then((r) => { if (!r.ok) throw new Error(`${name}.json HTTP ${r.status}`); return r.json(); }),
      ]);
      const m = parseGlb(buf);
      const gl = this.gl;
      const vao = gl.createVertexArray()!;
      gl.bindVertexArray(vao);
      const vb = (data: Float32Array, loc: number, size: number) => {
        const b = gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER, b); gl.bufferData(gl.ARRAY_BUFFER, data, gl.STATIC_DRAW);
        gl.enableVertexAttribArray(loc); gl.vertexAttribPointer(loc, size, gl.FLOAT, false, 0, 0);
      };
      vb(m.positions, 0, 3); vb(m.normals, 1, 3); vb(m.colors, 2, 4);
      const eb = gl.createBuffer(); gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, eb); gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, m.indices, gl.STATIC_DRAW);
      gl.bindVertexArray(null);
      const path = meta.camera?.type === 'path' ? parseCameraPath(meta.camera) : null;
      this.scenes[name] = { vao, count: m.indices.length, meta, path };
      delete this.errors[name];
      console.log(`Studio scene ${name}: ${m.positions.length / 3} verts, ${m.indices.length / 3} tris`);
    } catch (e) {
      this.errors[name] = e instanceof Error ? e.message : String(e);
      console.warn(`Studio scene ${name} failed: ${this.errors[name]}`);
    } finally {
      this.loading[name] = false;
    }
  }

  private ensureTargets(w: number, h: number) {
    const gl = this.gl;
    if (!this.shadowTex) {
      const t = gl.createTexture()!; gl.bindTexture(gl.TEXTURE_2D, t);
      gl.texStorage2D(gl.TEXTURE_2D, 1, gl.DEPTH_COMPONENT24, SHADOW_RES, SHADOW_RES);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR); gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE); gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_COMPARE_MODE, gl.COMPARE_REF_TO_TEXTURE); gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_COMPARE_FUNC, gl.LEQUAL);
      const f = gl.createFramebuffer()!; gl.bindFramebuffer(gl.FRAMEBUFFER, f);
      gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.DEPTH_ATTACHMENT, gl.TEXTURE_2D, t, 0);
      gl.drawBuffers([gl.NONE]); gl.readBuffer(gl.NONE);
      this.shadowTex = t; this.shadowFB = f;
    }
    if (this.size[0] === w && this.size[1] === h && this.resFB) return;
    if (this.msFB) { gl.deleteFramebuffer(this.msFB); gl.deleteRenderbuffer(this.msColor); gl.deleteRenderbuffer(this.msDepth); }
    if (this.resFB) { gl.deleteFramebuffer(this.resFB); gl.deleteTexture(this.resTex); }
    this.msColor = gl.createRenderbuffer(); gl.bindRenderbuffer(gl.RENDERBUFFER, this.msColor);
    gl.renderbufferStorageMultisample(gl.RENDERBUFFER, this.samples, gl.RGBA16F, w, h);
    this.msDepth = gl.createRenderbuffer(); gl.bindRenderbuffer(gl.RENDERBUFFER, this.msDepth);
    gl.renderbufferStorageMultisample(gl.RENDERBUFFER, this.samples, gl.DEPTH_COMPONENT24, w, h);
    this.msFB = gl.createFramebuffer(); gl.bindFramebuffer(gl.FRAMEBUFFER, this.msFB);
    gl.framebufferRenderbuffer(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.RENDERBUFFER, this.msColor);
    gl.framebufferRenderbuffer(gl.FRAMEBUFFER, gl.DEPTH_ATTACHMENT, gl.RENDERBUFFER, this.msDepth);
    this.resTex = gl.createTexture(); gl.bindTexture(gl.TEXTURE_2D, this.resTex);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA16F, w, h, 0, gl.RGBA, gl.HALF_FLOAT, null);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR); gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE); gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    this.resFB = gl.createFramebuffer(); gl.bindFramebuffer(gl.FRAMEBUFFER, this.resFB);
    gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, this.resTex, 0);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    this.size = [w, h];
  }

  /** DOF from a texture whose alpha holds view distance, drawn into `target`. Exposed for Morph sculpt. */
  dofPass(src: WebGLTexture, target: WebGLFramebuffer, w: number, h: number, focus: number, dof: number) {
    const gl = this.gl;
    gl.bindFramebuffer(gl.FRAMEBUFFER, target); gl.viewport(0, 0, w, h);
    gl.disable(gl.DEPTH_TEST); gl.disable(gl.BLEND);
    gl.useProgram(this.dof.p);
    gl.activeTexture(gl.TEXTURE0); gl.bindTexture(gl.TEXTURE_2D, src); gl.uniform1i(this.dof.u.uSrc, 0);
    gl.uniform2f(this.dof.u.uTexel, 1 / w, 1 / h);
    gl.uniform1f(this.dof.u.uFocus, focus);
    gl.uniform1f(this.dof.u.uAperture, dof * h / 1080 * 14);
    gl.uniform1f(this.dof.u.uMaxR, Math.max(1, 14 * h / 1080));
    gl.bindVertexArray(this.emptyVao);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
  }

  /** Scratch RGBA16F target sized w×h (for callers that render their own alpha=distance image, e.g. Morph). */
  scratch(w: number, h: number): { fb: WebGLFramebuffer; tex: WebGLTexture } {
    this.ensureTargets(w, h);
    return { fb: this.resFB!, tex: this.resTex! };
  }

  render(name: string, o: StudioRenderOpts): boolean {
    const sc = this.scenes[name];
    if (!sc) return false;
    const gl = this.gl;
    const p = o.params;
    const look = STUDIO_LOOKS[p.look] ?? STUDIO_LOOKS['Coral Peach'];
    this.ensureTargets(o.w, o.h);
    this.t += o.dt * p.speed;
    this.camT += o.dt * p.camSpeed;
    const meta = sc.meta;
    // ---- camera
    let eye: Vec3, tgt: Vec3, fov: number;
    const cam = meta.camera;
    if (cam.type === 'path' && sc.path) {
      const s = sampleCameraPath(sc.path, this.camT, 1);
      eye = s.position; tgt = s.target; fov = cam.fov ?? 60;
    } else {
      const ang = 0.6 + this.camT * (cam.speed ?? 0.05);
      const bob = (cam.bob ?? 0) * Math.sin(this.camT * 0.21);
      const t = cam.target as Vec3;
      eye = [t[0] + Math.sin(ang) * cam.radius, cam.height + bob, t[2] + Math.cos(ang) * cam.radius];
      tgt = t; fov = cam.fov ?? 38;
    }
    const view = lookAt(eye, tgt, [0, 1, 0]);
    const ext = Math.hypot(...sub(meta.bounds.max, meta.bounds.min));
    const proj = perspective(fov * Math.PI / 180, o.aspect, 0.05, Math.max(80, ext * 1.5));
    const vp = mul(proj, view);
    const fwd = norm(sub(tgt, eye));
    // ---- lights
    const az = p.keyAz * Math.PI / 180, el = p.keyEl * Math.PI / 180;
    // key az is relative to the camera so the look stays consistent while orbiting
    const camAz = Math.atan2(eye[0] - tgt[0], eye[2] - tgt[2]);
    const la = camAz + az;
    const Ld = norm([Math.sin(la) * Math.cos(el), Math.sin(el), Math.cos(la) * Math.cos(el)]);
    const Fd = norm([Math.sin(camAz - az * 1.3) * 0.8, 0.35, Math.cos(camAz - az * 1.3) * 0.8]);
    // shadow frustum: fit a sphere around the scene (tunnel: around the camera)
    let c: Vec3, rad: number;
    if (cam.type === 'path') { c = [eye[0] + fwd[0] * 9, eye[1] + fwd[1] * 9, eye[2] + fwd[2] * 9]; rad = 14; }
    else { c = [0, 1.2, 0]; rad = 7.5; }
    const lview = lookAt([c[0] + Ld[0] * 40, c[1] + Ld[1] * 40, c[2] + Ld[2] * 40], c, Math.abs(Ld[1]) > 0.95 ? [1, 0, 0] : [0, 1, 0]);
    const lproj = ortho(-rad, rad, -rad, rad, 1, 80);
    const lvp = mul(lproj, lview);
    // ---- layer angles
    const axes = new Float32Array(24), piv = new Float32Array(24), ang = new Float32Array(8);
    meta.layers.forEach((L, i) => {
      const k = i + 1; if (k > 7) return;
      axes.set(L.axis, k * 3); piv.set(L.pivot, k * 3); ang[k] = this.t * L.speed;
    });
    axes[1] = 1;
    const setLayers = (u: Record<string, WebGLUniformLocation | null>) => {
      gl.uniform3fv(u['uLAxis[0]'], axes); gl.uniform3fv(u['uLPivot[0]'], piv); gl.uniform1fv(u['uLAngle[0]'], ang);
    };
    // ---- shadow pass
    gl.bindFramebuffer(gl.FRAMEBUFFER, this.shadowFB); gl.viewport(0, 0, SHADOW_RES, SHADOW_RES);
    gl.enable(gl.DEPTH_TEST); gl.depthMask(true); gl.disable(gl.BLEND); gl.disable(gl.CULL_FACE);
    gl.clear(gl.DEPTH_BUFFER_BIT);
    gl.enable(gl.POLYGON_OFFSET_FILL); gl.polygonOffset(1.5, 3.0);
    gl.useProgram(this.shadow.p); gl.uniformMatrix4fv(this.shadow.u.uVP, false, lvp); setLayers(this.shadow.u);
    gl.bindVertexArray(sc.vao); gl.drawElements(gl.TRIANGLES, sc.count, gl.UNSIGNED_INT, 0);
    gl.disable(gl.POLYGON_OFFSET_FILL);
    // ---- main pass (MSAA)
    gl.bindFramebuffer(gl.FRAMEBUFFER, this.msFB); gl.viewport(0, 0, o.w, o.h);
    gl.clearColor(0, 0, 0, 1000); gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
    const L3 = (hx: string, s = 1): Vec3 => { const v = srgbHex(hx); return [v[0] * s, v[1] * s, v[2] * s]; };
    const keyC = L3(look.key), fillC = L3(look.fill);
    const setEnv = (u: Record<string, WebGLUniformLocation | null>) => {
      gl.uniform3fv(u.uBgTop, L3(look.bgTop)); gl.uniform3fv(u.uBgBottom, L3(look.bgBottom)); gl.uniform3fv(u.uBgGlow, L3(look.glow, 0.25));
      gl.uniform3fv(u.uKeyCol, keyC); gl.uniform3fv(u.uFillCol, fillC); gl.uniform3fv(u.uLightDir, Ld); gl.uniform3fv(u.uFillDir, Fd);
      gl.uniform3fv(u.uCamFwd, fwd); gl.uniform1f(u.uBoxI, 1.0);
    };
    gl.disable(gl.DEPTH_TEST); gl.depthMask(false);
    gl.useProgram(this.back.p); setEnv(this.back.u);
    gl.uniformMatrix4fv(this.back.u.uInvVP, false, invert(vp)); gl.uniform3fv(this.back.u.uCamPos, eye);
    gl.bindVertexArray(this.emptyVao); gl.drawArrays(gl.TRIANGLES, 0, 3);
    gl.enable(gl.DEPTH_TEST); gl.depthMask(true); gl.depthFunc(gl.LESS);
    const u = this.mesh.u;
    gl.useProgram(this.mesh.p); setEnv(u); setLayers(u);
    gl.uniformMatrix4fv(u.uVP, false, vp); gl.uniformMatrix4fv(u.uLightVP, false, lvp); gl.uniform3fv(u.uCamPos, eye);
    gl.activeTexture(gl.TEXTURE3); gl.bindTexture(gl.TEXTURE_2D, this.shadowTex); gl.uniform1i(u.uShadow, 3);
    gl.uniform1f(u.uShadowSoft, p.shadowSoft); gl.uniform1f(u.uShadowTexel, 1 / SHADOW_RES);
    const slots = new Float32Array(24);
    look.slots.forEach((h, i) => slots.set(srgbHex(h), i * 3));
    // floor albedo chosen so the lit floor meets the cove colour seamlessly
    const bb = srgbHex(look.bgBottom); const lit = look.keyI * Math.max(0.2, Math.sin(el)) * 0.95 + look.domeI * 0.95;
    slots.set([bb[0] / lit, bb[1] / lit, bb[2] / lit], 21);
    gl.uniform3fv(u['uSlots[0]'], slots);
    gl.uniform3fv(u.uDomeCol, L3(look.dome)); gl.uniform3fv(u.uGroundCol, [bb[0] * 0.8, bb[1] * 0.8, bb[2] * 0.8]); gl.uniform3fv(u.uRimCol, L3(look.rim));
    gl.uniform1f(u.uKeyI, look.keyI); gl.uniform1f(u.uDomeI, look.domeI);
    gl.uniform1f(u.uRim, p.rim); gl.uniform1f(u.uAO, p.ao); gl.uniform1f(u.uGloss, p.gloss); gl.uniform1f(u.uIrid, p.irid);
    gl.uniform1f(u.uFloorFade, cam.type === 'path' ? 1e4 : 16.0); gl.uniform1f(u.uFog, p.fog);
    gl.uniform1f(u.uMatOverride, Math.max(-1, STUDIO_MATS.indexOf(p.mat) - 1));
    gl.uniform1f(u.uTime, this.t); gl.uniform1f(u.uSpecI, 1.0);
    gl.bindVertexArray(sc.vao); gl.drawElements(gl.TRIANGLES, sc.count, gl.UNSIGNED_INT, 0);
    gl.bindVertexArray(null);
    gl.activeTexture(gl.TEXTURE3); gl.bindTexture(gl.TEXTURE_2D, null); gl.activeTexture(gl.TEXTURE0);
    // ---- resolve + DOF into the caller's target
    gl.bindFramebuffer(gl.READ_FRAMEBUFFER, this.msFB); gl.bindFramebuffer(gl.DRAW_FRAMEBUFFER, this.resFB);
    gl.blitFramebuffer(0, 0, o.w, o.h, 0, 0, o.w, o.h, gl.COLOR_BUFFER_BIT, gl.NEAREST);
    gl.bindFramebuffer(gl.READ_FRAMEBUFFER, null); gl.bindFramebuffer(gl.DRAW_FRAMEBUFFER, null);
    gl.disable(gl.DEPTH_TEST);
    const focus = p.focus > 0 ? p.focus : (cam.focus ?? Math.hypot(...sub(tgt, eye)));
    this.dofPass(this.resTex!, o.target, o.w, o.h, focus, p.dof);
    this.lastDebug = { scene: name, eye, tgt, fov, focus, samples: this.samples, tris: sc.count / 3 };
    return true;
  }
}
